.home{max-width:1420px;margin:auto}.promo{background:linear-gradient(110deg,#ff665d,#ff956b);color:white;border-radius:10px;padding:38px 44px;display:flex;justify-content:space-between;align-items:center}.promo h1{font-size:32px;margin:0 0 10px}.promo p{margin:0;opacity:.9}.promo .el-button{color:#ff665d;border:0;font-weight:700}.categories{display:flex;flex-wrap:wrap;gap:6px;background:#fff;border:1px solid #e3ebef;border-radius:10px;padding:16px 18px;margin-top:18px}.categories button{border:0;background:transparent;padding:9px 14px;color:#53697b;cursor:pointer;border-radius:20px;font-size:14px}.categories button.active{background:#ff665d;color:#fff}.search{display:flex;gap:14px;background:#fff;border:1px solid #e3ebef;border-radius:10px;padding:20px;margin-top:14px}.search .el-input{flex:1}.section-title{font-size:22px;margin:28px 0 16px}.product-card{background:#fff;border:1px solid #e2ebf0;border-radius:10px;overflow:hidden;cursor:pointer;transition:.2s}.product-card:hover{transform:translateY(-3px);box-shadow:0 10px 24px rgba(34,75,100,.1)}.product-image{width:100%;height:230px;display:block}.product-body{padding:14px 16px}.product-body .el-tag{margin-right:6px}.product-body h3{font-size:17px;margin:12px 0 8px;color:#1e2e3d;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.product-body p{height:42px;color:#778b9a;margin:0;font-size:13px;line-height:1.6}.price{color:#ff5c4f;font-size:23px;font-weight:800;margin-top:14px}
